	def provider(self) -> str:
		return 'mistral'

	@property
	def name(self) -> str:
		return str(self.model)

	def _get_api_key(self) -> str:
		key = self.api_key or os.getenv('MISTRAL_API_KEY')
		if not key:
			raise ModelProviderError('Missing Mistral API key', status_code=401, model=self.name)
		return key

	def _get_base_url(self) -> str:
		return str(os.getenv('MISTRAL_BASE_URL', self.base_url)).rstrip('/')

	def _auth_headers(self) -> dict[str, str]:
		headers = {
			'Authorization': f'Bearer {self._get_api_key()}',
			'Content-Type': 'application/json',
		}
		if self.default_headers:
			headers.update(self.default_headers)
		return headers

	def _client(self) -> httpx.AsyncClient:
		if self.http_client:
			return self.http_client

		if not hasattr(self, '_cached_client'):
			transport = httpx.AsyncHTTPTransport(retries=self.max_retries)
			client_args: dict[str, Any] = {'transport': transport}
			if self.timeout is not None:
				client_args['timeout'] = self.timeout
			self._cached_client = httpx.AsyncClient(**client_args)
		return self._cached_client

	def _serialize_messages(self, messages: list[BaseMessage]) -> list[dict[str, Any]]:
		raw_messages: list[dict[str, Any]] = []
		for msg in OpenAIMessageSerializer.serialize_messages(messages):
			dumper = getattr(msg, 'model_dump', None)
			if callable(dumper):
				raw_messages.append(cast(dict[str, Any], dumper(exclude_none=True)))
			else:
				raw_messages.append(cast(dict[str, Any], msg))  # type: ignore[arg-type]
		return raw_messages

	def _query_params(self) -> dict[str, str] | None:
		if self.default_query is None:
			return None
		return {k: str(v) for k, v in self.default_query.items() if v is not None}

	def _build_usage(self, usage: dict[str, Any] | None) -> ChatInvokeUsage | None:
		if not usage:
			return None

		return ChatInvokeUsage(
			prompt_tokens=usage.get('prompt_tokens', 0),
			prompt_cached_tokens=None,
			prompt_cache_creation_tokens=None,
			prompt_image_tokens=None,
			completion_tokens=usage.get('completion_tokens', 0),
			total_tokens=usage.get('total_tokens', 0),
		)

	def _extract_content_text(self, choice: dict[str, Any]) -> str:
		message = choice.get('message', {})
		content = message.get('content')

		if isinstance(content, list):
			text_parts = []
			for part in content:
				if isinstance(part, dict):
					if part.get('type') == 'text' and 'text' in part:
						text_parts.append(part.get('text', ''))
					elif 'content' in part:
						text_parts.append(str(part['content']))
			return ''.join(text_parts)

		if isinstance(content, dict):
			return json.dumps(content)

		return content or ''

	def _parse_error(self, response: httpx.Response) -> str:
		try:
			body = response.json()
			if isinstance(body, dict):
				for key in ('message', 'error', 'detail'):
					val = body.get(key)
					if isinstance(val, dict):
						val = val.get('message') or val.get('detail')
					if val:
						return str(val)
		except Exception:
			pass
		return response.text

	async def _post(self, payload: dict[str, Any]) -> dict[str, Any]:
		url = f'{self._get_base_url()}/chat/completions'
		client = self._client()
		response = await client.post(url, headers=self._auth_headers(), json=payload, params=self._query_params())

		if response.status_code >= 400:
			message = self._parse_error(response)
			if response.status_code == 429:
				raise ModelRateLimitError(message=message, status_code=response.status_code, model=self.name)
			raise ModelProviderError(message=message, status_code=response.status_code, model=self.name)

		try:
			return response.json()
		except Exception as e:
			raise ModelProviderError(message=f'Failed to parse Mistral response: {e}', model=self.name) from e

	@overload
	async def ainvoke(
		self, messages: list[BaseMessage], output_format: None = None, **kwargs: Any
	) -> ChatInvokeCompletion[str]: ...

	@overload
	async def ainvoke(self, messages: list[BaseMessage], output_format: type[T], **kwargs: Any) -> ChatInvokeCompletion[T]: ...

	async def ainvoke(
		self, messages: list[BaseMessage], output_format: type[T] | None = None, **kwargs: Any
	) -> ChatInvokeCompletion[T] | ChatInvokeCompletion[str]:
		payload: dict[str, Any] = {
			'model': self.model,
			'messages': self._serialize_messages(messages),
		}

		# Generation params
		if self.temperature is not None:
			payload['temperature'] = self.temperature
		if self.top_p is not None:
			payload['top_p'] = self.top_p
		if self.max_tokens is not None:
			payload['max_tokens'] = self.max_tokens
		if self.seed is not None:
			payload['seed'] = self.

        return OpenAIModel(
            api_key=api_key or os.getenv("FIREWORKS_API_KEY"),
            api_base=api_base or "https://api.fireworks.ai/inference/v1",
            model_id=model_id,
        )
    elif model_type == "LiteLLMModel":
        return LiteLLMModel(
            model_id=model_id,
            api_key=api_key,
            api_base=api_base,
        )
    elif model_type == "TransformersModel":
        return TransformersModel(model_id=model_id, device_map="auto")
    elif model_type == "InferenceClientModel":
        return InferenceClientModel(
            model_id=model_id,
            token=api_key or os.getenv("HF_API_KEY"),
            provider=provider,
        )
    else:
        raise ValueError(f"Unsupported model type: {model_type}")


def run_smolagent(
    prompt: str,
    tools: list[str],
    model_type: str,
    model_id: str,
    api_base: str | None = None,
    api_key: str | None = None,
    imports: list[str] | None = None,
    provider: str | None = None,
    action_type: str = "code",
) -> None:
    load_dotenv()

    model = load_model(model_type, model_id, api_base=api_base, api_key=api_key, provider=provider)

    available_tools = []

    for tool_name in tools:
        if "/" in tool_name:
            space_name = tool_name.split("/")[-1].lower().replace("-", "_").replace(".", "_")
            description = f"Tool loaded from Hugging Face Space: {tool_name}"
            available_tools.append(Tool.from_space(space_id=tool_name, name=space_name, description=description))
        else:
            if tool_name in TOOL_MAPPING:
                available_tools.append(TOOL_MAPPING[tool_name]())
            else:
                raise ValueError(f"Tool {tool_name} is not recognized either as a default tool or a Space.")

    if action_type == "code":
        agent = CodeAgent(
            tools=available_tools,
            model=model,
            additional_authorized_imports=imports,
            stream_outputs=True,
        )
    elif action_type == "tool_calling":
        agent = ToolCallingAgent(tools=available_tools, model=model, stream_outputs=True)
    else:
        raise ValueError(f"Unsupported action type: {action_type}")

    agent.run(prompt)


def main() -> None:
    args = parse_arguments()

    # Check if we should run in interactive mode
    # Interactive mode is triggered when no prompt is provided
    if args.prompt is None:
        prompt, tools, model_type, model_id, provider, api_base, api_key, imports, action_type = interactive_mode()
    else:
        prompt = args.prompt
        tools = args.tools
        model_type = args.model_type
        model_id = args.model_id
        provider = args.provider
        api_base = args.api_base
        api_key = args.api_key
        imports = args.imports
        action_type = args.action_type

    run_smolagent(
        prompt,
        tools,
        model_type,
        model_id,
        provider=provider,
        api_base=api_base,
        api_key=api_key,
        imports=imports,
        action_type=action_type,
    )


if __name__ == "__main__":
    main()

